main.tf:
resource "aws_s3_bucket" "cloudagentra_storage_bucket" {
  bucket        = "cloudagentra-storage-bucket-12738"
  force_destroy = false

  tags = {
    Name  = "cloudagentra-storage-bucket-12738"
    Stack = "s3-bucket"
  }
}

resource "aws_s3_bucket_versioning" "cloudagentra_storage_bucket_versioning" {
  bucket = aws_s3_bucket.cloudagentra_storage_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "cloudagentra_storage_bucket_pab" {
  bucket = aws_s3_bucket.cloudagentra_storage_bucket.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

outputs.tf:
output "bucket_id" {
  description = "The name (ID) of the S3 bucket."
  value       = aws_s3_bucket.cloudagentra_storage_bucket.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.cloudagentra_storage_bucket.arn
}

output "bucket_region" {
  description = "The AWS region where the S3 bucket was created."
  value       = aws_s3_bucket.cloudagentra_storage_bucket.region
}

output "versioning_status" {
  description = "The versioning status of the S3 bucket."
  value       = aws_s3_bucket_versioning.cloudagentra_storage_bucket_versioning.versioning_configuration[0].status
}
